    let config = ?kitConfiguration(init, configurationRoots, kitConfigurationSchema(), configurationRoot)
    let r = initModule(T, init, fromChecked(TunerConfig, config))
    if r.isErr:
      return err(r.error)
    let instance = r.get
    if instance.isNil:
      return err(moduleError("initModule returned nil"))
    GC_ref(instance)
    ok(cast[pointer](instance))

